"""Source-first activation of an existing, semantically identical watch record."""
from daily22 import ROOT,RUN,read,write,now,attempts
import hashlib,json
cat=read(ROOT/'data/trials_base.json');row=next(x for x in cat if x['id']=='mizzou-feline-highgrade-lymphoma-wart')
a=next(x for x in attempts() if x['source_id']=='usa-missouri-oncology-clinical-trials' and x.get('http_status')==200)
e=read(ROOT/a['evidence_file']);text=e['text'];start=text.index('Feline GI Lymphoma Radiation + Chemotherapy');end=text.index('Gilvetmab for the Treatment',start);facts=text[start:end]
assert 'is enrolling patients' in facts and 'large cell GI lymphoma' in facts and '$1,000' in facts
# Expectations are derived from this complete published study section before matcher execution.
review={'trial_id':row['id'],'source_url':a['url'],'reviewed_at':now(),'source_attempt':{k:a[k] for k in ['method','attempted_at','evidence_file']},'criteria':'Missouri currently enrolls cats with cytology/histology-confirmed high-grade/large-cell gastrointestinal lymphoma confined to the abdomen, chemotherapy-naive, FeLV/FIV-negative and fit for anesthesia. Whole-abdomen radiation precedes COP/doxorubicin chemotherapy. Radiation is funded and $1,000 VHC credit follows radiation; screening/chemotherapy/travel costs are not stated. Weekly visits at least eight weeks, then five visits every three weeks. No separate protocol link is published; the named full primary study section is the protocol.',
'cases':[{'name':'untreated cat with investigator screening of abdominal GI grade','patient':{'species':'Cat','country':'USA','cancer':'Lymphoma — other','chemo':'Never received'},'expected':'review'}, {'name':'unknown diagnosis certainty and treatment history remain screening','patient':{'species':'Cat','country':'USA','cancer':'Lymphoma — other'},'expected':'review','unknown_contains':['high-grade','FeLV']}, {'name':'previous chemotherapy contradicts naive enrollment','patient':{'species':'Cat','country':'USA','cancer':'Lymphoma — other','chemo':'Previously received'},'expected':'exclude'}, {'name':'current chemotherapy contradicts naive enrollment','patient':{'species':'Cat','country':'USA','cancer':'Lymphoma — other','chemo':'Currently receiving'},'expected':'exclude'}, {'name':'radiation without required chemotherapy is not protocol','patient':{'species':'Cat','country':'USA','cancer':'Lymphoma — other','prefs':['Radiation']},'expected':'exclude'}, {'name':'chemotherapy without required radiation is not protocol','patient':{'species':'Cat','country':'USA','cancer':'Lymphoma — other','prefs':['Chemotherapy']},'expected':'exclude'}, {'name':'dog cannot enter feline cohort','patient':{'species':'Dog','country':'USA','cancer':'Lymphoma — other'},'expected':'exclude'}, {'name':'oral SCC is a different disease','patient':{'species':'Cat','country':'USA','cancer':'Oral squamous cell carcinoma'},'expected':'exclude'}, {'name':'no Canadian study site published','patient':{'species':'Cat','country':'Canada','cancer':'Lymphoma — other'},'expected':'exclude'}]}
write(RUN/'missouri-independent-review-before-matcher.json',review)
write(RUN/'missouri-primary-section.json',{'at':now(),'attempt':a,'section':facts,'all_linked_protocol_or_pdf_routes':[z for z in e['links'] if 'lymphoma' in z['url'].lower() or 'wart' in z['url'].lower()],'semantic_dedupe':{'catalog_records_inspected':len(cat),'existing_identity':row['id'],'same_species_diagnosis_intervention_center':True,'not_duplicate_of':'tamu-feline-small-cell-gi-lymphoma-wart','distinction':'Missouri high-grade/large-cell untreated GI lymphoma with WART followed by COP/doxorubicin versus Texas A&M small-cell relapsed/difficult-to-medicate GI lymphoma radiation.'}})
row.update(title='Whole-abdomen radiation followed by COP/doxorubicin for feline high-grade gastrointestinal lymphoma',cancers=['B-cell lymphoma','T-cell lymphoma','Lymphoma — other'],status='Currently enrolling — University of Missouri Veterinary Health Center',status_confidence='confirmed_current',available_for_matching=True,url=a['url'],source_url=a['url'],verified=a['attempted_at'][:10],owner_prescreen_required=True,requires={'confirmed':True,'planned_radiation':True,'planned_chemo':True,'high_grade_abdominal_gi_lymphoma':True,'felv_fiv_negative':True},excludes={'prior_chemo':True,'current_chemo':True,'small_cell_lymphoma':True,'severe_systemic_disease':True},funding='Partially funded. The study covers whole-abdomen radiation and provides a $1,000 credit for care at the VHC after radiation is completed. Published information does not specify screening, COP/doxorubicin chemotherapy, other care or travel coverage; confirm these costs with the study team.',funding_status='Partially funded; radiation covered and $1,000 VHC credit after radiation',funding_source=a['url'],funding_verified=a['attempted_at'][:10],contacts='Oncology Clinical Trials — cvmclinicaltrials@missouri.edu; VHC 573-882-7821',contact='Oncology Clinical Trials — cvmclinicaltrials@missouri.edu; VHC 573-882-7821',contact_source=a['url'],intervention='Whole-abdomen radiation therapy followed by COP/doxorubicin chemotherapy',treatments=['Radiation','Chemotherapy'],treatment_approaches=['radiation_innovation','chemotherapy'],special_requirement='Cytology or histopathology must confirm high-grade / large-cell gastrointestinal lymphoma confined to the abdomen. No previous chemotherapy; FeLV/FIV-negative and suitable for anesthesia. Investigator screening includes blood count, chemistry, urinalysis, chest radiographs and abdominal ultrasound. Visits in Columbia, Missouri weekly for at least eight weeks, then every three weeks for five more visits.',notes='The current official named protocol now explicitly invites enrollment, replacing the earlier award-only watch signal. High-grade/large-cell GI disease and absence of lymphoma outside the abdomen require investigator confirmation; a general lymphoma match is prescreening only. Radiation is delivered during the first week, followed by COP/doxorubicin. Screening, chemotherapy, other care and travel coverage are not stated. This is distinct from the Texas A&M small-cell GI lymphoma radiation protocol.')
write(ROOT/'data/trials_base.json',cat)
rules=read(ROOT/'data/matcher_protocol_rules.json');rules['requires']['high_grade_abdominal_gi_lymphoma']={'label':'high-grade / large-cell gastrointestinal lymphoma confined to the abdomen'};rules['requires']['felv_fiv_negative']={'label':'negative FeLV and FIV testing'};write(ROOT/'data/matcher_protocol_rules.json',rules)
b=read(ROOT/'data/protocol_selection_baseline.json')
def stable(v):return {k:stable(v[k]) for k in sorted(v)} if isinstance(v,dict) else [stable(x) for x in v] if isinstance(v,list) else v
sig=hashlib.sha256(json.dumps(stable({k:row.get(k) for k in b['signature_fields']}),ensure_ascii=False,separators=(',',':')).encode()).hexdigest();review['selection_sha256']=sig
cases=read(ROOT/'data/protocol_selection_cases.json');cases['reviews']=[x for x in cases['reviews'] if x['trial_id']!=row['id']]+[review];write(ROOT/'data/protocol_selection_cases.json',cases)
write(RUN/'catalog-changes.json',{'at':now(),'new_record_ids':[],'activated_existing_watch_ids':[row['id']],'substantive_updated_ids':[row['id']],'hidden_ids':[],'deleted_ids':[],'primary_evidence':a['evidence_file'],'independent_review':str((RUN/'missouri-independent-review-before-matcher.json').relative_to(ROOT))})
print('Reviewed and activated existing watch identity',row['id'])
